def sub(path, old, new):
    p = Path(path); s = p.read_text(); assert s.count(old) == 1, (path, old); p.write_text(s.replace(old, new))

sub("src/trailhead/track.py", '''    def length_km(self) -> float:
        return sum(self.leg_lengths_km())
''', '''    def length_km(self) -> float:
        return sum(self.leg_lengths_km())

    def elevations(self) -> list[float]:
        """Elevation of every point in metres, with the missing ones filled in.

        A point without an elevation takes that of the nearest earlier point that
        has one or, if there is none, of the nearest later point. A track with
        points but no elevation at all is a `TrackError`.
        """
        first = next((p.ele for p in self.points if p.ele is not None), None)
        if first is None:
            if self.points:
                raise TrackError("the track has no elevations")
            return []
        filled: list[float] = []
        current = first
        for point in self.points:
            if point.ele is not None:
                current = point.ele
            filled.append(current)
        return filled
''')
sub("src/trailhead/elevation.py", '''    elevations = [point.ele for point in track.points]
    return max''', '''    elevations = track.elevations()
    return max''')
sub("src/trailhead/elevation.py", '''    for (a, b), km in zip(pairwise(track.points), track.leg_lengths_km(), strict=True):
        if km == 0:
            continue
        steepest = max(steepest, abs(b.ele - a.ele) / (km * 1000) * 100)''', '''    for (a, b), km in zip(pairwise(track.elevations()), track.leg_lengths_km(), strict=True):
        if km == 0:
            continue
        steepest = max(steepest, abs(b - a) / (km * 1000) * 100)''')
sub("src/trailhead/pace.py", "counted_changes([p.ele for p in track.points])", "counted_changes(track.elevations())")
sub("src/trailhead/report.py", "gain_and_loss([point.ele for point in track.points], threshold)", "gain_and_loss(track.elevations(), threshold)")
sub("src/trailhead/cli.py", '''    try:
        track = load_track(args.file)
    except (OSError, TrackError) as exc:
        print(f"trailhead: {exc}", file=sys.stderr)
        return 1
    if args.command == "summary":
        print(format_summary(summarise(track, args.fitness, args.threshold)))
    else:
        for line in describe_plan(split_days(track, args.max_hours, args.fitness)):
            print(line)
    return 0''', '''    try:
        track = load_track(args.file)
        if args.command == "summary":
            lines = [format_summary(summarise(track, args.fitness, args.threshold))]
        else:
            lines = describe_plan(split_days(track, args.max_hours, args.fitness))
    except (OSError, TrackError) as exc:
        print(f"trailhead: {exc}", file=sys.stderr)
        return 1
    for line in lines:
        print(line)
    return 0''')
EOF
